        float activeAt=-1;
        void Update()
        {
            delta+=Time.unscaledDeltaTime;frames++;if(done||late||!P)return;var match=WildfrontMatch.Current;var draft=SpawnDraft.Current;
            if(match&&match.Round.Value!=observedRound){observedRound=match.Round.Value;submitted=picked=false;}
            if(draft&&draft.TurnPlayer.Value==P.NetworkObjectId)
            {
                if(match.Phase.Value==3&&!submitted){submitted=true;int bid=(int)S.Network.LocalClientId*2;draft.PreviewServerRpc(bid,S.IsHost?5:2,(int)S.Network.LocalClientId);draft.SubmitBidServerRpc(bid,S.IsHost?5:2);}
                if(match.Phase.Value==4&&!picked){picked=true;if(S.IsHost)draft.PickPointServerRpc(new Vector3(330,0,-570));else for(int i=0;i<ExpeditionLayout.Regions.Length;i++)if(!draft.Claimed(i)){draft.PickRegionServerRpc(i);break;}}
            }
            if(!S.IsHost&&!match.Active)
            {var drop=WorldLoot.All.FirstOrDefault(l=>l&&l.Kind.Value==1&&l.Item.Value==2&&l.Amount.Value==17&&Mathf.Abs(l.transform.position.x)<10&&l.transform.position.z< -130&&l.transform.position.z> -180);if(drop){P.SmokeMoveTo(ReserveWorld.OnGround(drop.transform.position.x,drop.transform.position.z,.2f));P.ScavengeServerRpc(drop.NetworkObjectId);}}
            if(match&&match.Active)
            {
                if(activeAt<0)activeAt=Time.time;float elapsed=Time.time-activeAt;
                if(elapsed<40){var host=Ranger.Players.FirstOrDefault(q=>q&&!q.IsBot.Value&&q.OwnerClientId==0);float x=S.IsHost?0:host&&P.Team.Value==host.Team.Value?2:elapsed<17?25:110;P.SmokeMoveTo(ReserveWorld.OnGround(x,-100,.3f));if(Time.time>voiceAt){voiceAt=Time.time+.04f;ProximityVoice.Current.Transmit(tone);}}
            }
            if(Time.realtimeSinceStartup-began>110)Finish();
        }
        void Write(){string path=ReserveSession.Arg("--report");if(path!="")File.WriteAllText(path,JsonUtility.ToJson(report,true));}
        void Finish(){if(done)return;done=true;report.voiceFrames=ProximityVoice.Current?ProximityVoice.Current.ReceivedFrames:0;report.fps=frames/Mathf.Max(.01f,delta);Write();Application.Quit();}
        void OnDestroy(){Application.logMessageReceived-=Log;}
    }
